<?php
declare(strict_types=1);
/** Administrator-only maintenance storage. Never expose settings/token files to HTTP. */
function sfem_root():string{if(PHP_SAPI==='cli'&&defined('SFEM_TEST_ROOT'))return SFEM_TEST_ROOT;return dirname(__DIR__);}
function sfem_files():array{return ['lib/external_services.php','lib/external_youtube.php','lib/external_cover.php','lib/external_lyrics.php','lib/external_album.php','lib/external_charts.php','lib/external_charts_audio.php','lib/external_mornye.php'];}
function sfem_file(string $name):string{if(!in_array($name,sfem_files(),true))throw new RuntimeException('Archivo no permitido.');$p=sfem_root().'/'.$name;if(is_link($p)||realpath(dirname($p))!==sfem_root().'/lib')throw new RuntimeException('Ruta de integración inválida.');return $p;}
function sfem_dir():string{$p=sfem_root().'/data/external-ai';if(!is_dir($p)&&!mkdir($p,02770,true)&&!is_dir($p))throw new RuntimeException('No se pudo crear el directorio de mantenimiento.');chmod($p,02770);return $p;}
function sfem_write(string $path,string $body,int $mode=0660):void{$tmp=$path.'.'.bin2hex(random_bytes(6)).'.tmp';if(file_put_contents($tmp,$body,LOCK_EX)===false)throw new RuntimeException('No se pudo guardar el archivo.');chmod($tmp,$mode);if(!rename($tmp,$path)){@unlink($tmp);throw new RuntimeException('No se pudo publicar el archivo.');}}
function sfem_json(string $path,array $value):void{sfem_write($path,json_encode($value,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));}
function sfem_read_json(string $path):array{$d=is_file($path)?json_decode((string)file_get_contents($path),true):[];return is_array($d)?$d:[];}
function sfem_defaults():array{return ['provider'=>'openai','daily'=>true,'interval_days'=>1,'auto_apply'=>true,'max_tokens'=>12000,'providers'=>[
 'openai'=>['name'=>'OpenAI','url'=>'https://api.openai.com/v1/chat/completions','protocol'=>'openai','model'=>'','token'=>''],
 'grok'=>['name'=>'Grok (xAI)','url'=>'https://api.x.ai/v1/chat/completions','protocol'=>'chat','model'=>'','token'=>''],
 'deepseek'=>['name'=>'DeepSeek','url'=>'https://api.deepseek.com/chat/completions','protocol'=>'chat','model'=>'','token'=>''],
 'claude'=>['name'=>'Claude','url'=>'https://api.anthropic.com/v1/messages','protocol'=>'anthropic','model'=>'','token'=>'']]];}
function sfem_settings():array{$d=sfem_read_json(sfem_dir().'/settings.json');$v=sfem_defaults();foreach(['provider','daily','interval_days','auto_apply','max_tokens'] as $k)if(array_key_exists($k,$d))$v[$k]=$d[$k];foreach($d['providers']??[] as $k=>$p)if(is_array($p))$v['providers'][$k]=$p;return $v;}
function sfem_key():string{if(!function_exists('sodium_crypto_secretbox'))throw new RuntimeException('El cifrado Sodium no está disponible.');$p=sfem_dir().'/token.key';if(!is_file($p)){$f=@fopen($p,'x');if($f){chmod($p,0600);fwrite($f,random_bytes(SODIUM_CRYPTO_SECRETBOX_KEYBYTES));fclose($f);}}$key=(string)file_get_contents($p);if(strlen($key)!==SODIUM_CRYPTO_SECRETBOX_KEYBYTES)throw new RuntimeException('Clave de cifrado inválida.');return $key;}
function sfem_encrypt(string $token):string{$nonce=random_bytes(SODIUM_CRYPTO_SECRETBOX_NONCEBYTES);return base64_encode($nonce.sodium_crypto_secretbox($token,$nonce,sfem_key()));}
function sfem_decrypt(string $encrypted):string{$raw=base64_decode($encrypted,true);if(!is_string($raw)||strlen($raw)<SODIUM_CRYPTO_SECRETBOX_NONCEBYTES)throw new RuntimeException('Token guardado inválido.');$token=sodium_crypto_secretbox_open(substr($raw,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),substr($raw,0,SODIUM_CRYPTO_SECRETBOX_NONCEBYTES),sfem_key());if($token===false)throw new RuntimeException('No se pudo descifrar el token.');return $token;}
function sfem_public_settings():array{$s=sfem_settings();foreach($s['providers'] as &$p){$p['has_token']=!empty($p['token']);unset($p['token']);}return $s;}
function sfem_save_settings_unlocked(array $input):void{
 $s=sfem_settings();$id=(string)($input['provider']??'');if(!preg_match('/^[a-z][a-z0-9_-]{0,39}$/D',$id))throw new RuntimeException('Identificador de proveedor inválido.');
 $p=$s['providers'][$id]??[];$p['name']=trim((string)($input['name']??$p['name']??''));$p['url']=trim((string)($input['url']??$p['url']??''));$p['protocol']=(string)($input['protocol']??$p['protocol']??'chat');$p['model']=trim((string)($input['model']??''));
 if($p['name']===''||strlen($p['name'])>100||!in_array($p['protocol'],['openai','chat','anthropic'],true)||($p['model']!==''&&!preg_match('/^[a-zA-Z0-9._:\/-]{1,120}$/D',$p['model'])))throw new RuntimeException('Revisa el nombre, protocolo y modelo de API.');
 sfem_validate_url($p['url'],false);
 if(isset($input['pricing_model'])&&$input['pricing_model']===$p['model']){$rates=['model'=>$p['model'],'updated_at'=>gmdate('c')];foreach(['input','cached','output','cache_write','cache_write_1h'] as $kind){$value=trim((string)($input['price_'.$kind]??''));if($value===''){$rates[$kind]=null;continue;}if(!is_numeric($value)||!is_finite((float)$value)||(float)$value<0||(float)$value>100000)throw new RuntimeException('Tarifa de tokens inválida.');$rates[$kind]=(float)$value;}$p['pricing']=$rates;}
 elseif(($p['pricing']['model']??'')!==$p['model'])unset($p['pricing']);

 $token=trim((string)($input['token']??''));if($token!==''&&(strlen($token)>4096||preg_match('/[\x00-\x20\x7f]/',$token)))throw new RuntimeException('Token inválido.');if($token!=='')$p['token']=sfem_encrypt($token);if(!empty($input['delete_token']))$p['token']='';
 $days=filter_var($input['interval_days']??$s['interval_days']??1,FILTER_VALIDATE_INT,['options'=>['min_range'=>1,'max_range'=>3650]]);if($days===false)throw new RuntimeException('El intervalo debe ser un número entero de 1 a 3650 días.');$s['interval_days']=$days;$s['providers'][$id]=$p;$s['provider']=$id;$s['daily']=!empty($input['daily']);$s['auto_apply']=!empty($input['auto_apply']);$s['max_tokens']=max(2000,min(16000,(int)($input['max_tokens']??12000)));sfem_json(sfem_dir().'/settings.json',$s);
}
function sfem_sources():array{$out=[];foreach(sfem_files() as $file)$out[$file]=(string)file_get_contents(sfem_file($file));return $out;}
function sfem_hashes():array{return array_map(static fn($s)=>hash('sha256',$s),sfem_sources());}
function sfem_versions_dir():string{$p=sfem_root().'/backups/external-services';if(!is_dir($p)&&!mkdir($p,02770,true)&&!is_dir($p))throw new RuntimeException('No se pudo crear el respaldo.');chmod($p,02770);return $p;}
function sfem_snapshot(string $actor,string $reason):string{$id=gmdate('Ymd-His').'-'.bin2hex(random_bytes(5));$p=sfem_versions_dir().'/'.$id;if(!mkdir($p,02770))throw new RuntimeException('No se pudo respaldar.');chmod($p,02770);$hashes=[];foreach(sfem_sources() as $file=>$source){sfem_write($p.'/'.basename($file),$source);$hashes[$file]=hash('sha256',$source);}sfem_json($p.'/manifest.json',['id'=>$id,'created_at'=>gmdate('c'),'actor'=>$actor,'reason'=>$reason,'hashes'=>$hashes]);return $id;}
function sfem_versions():array{$out=[];foreach(glob(sfem_versions_dir().'/*/manifest.json')?:[] as $p)$out[]=sfem_read_json($p);usort($out,static fn($a,$b)=>strcmp($b['id']??'',$a['id']??''));return array_slice($out,0,100);}
function sfem_version_sources(string $id):array{if(!preg_match('/^\d{8}-\d{6}-[a-f0-9]{10}$/D',$id))throw new RuntimeException('Versión inválida.');$p=sfem_versions_dir().'/'.$id;$meta=sfem_read_json($p.'/manifest.json');$out=[];foreach(sfem_files() as $file){if(in_array($file,['lib/external_album.php','lib/external_charts.php','lib/external_charts_audio.php','lib/external_mornye.php'],true)&&!array_key_exists($file,$meta['hashes']??[])){$out[$file]=(string)file_get_contents(sfem_file($file));continue;}$body=@file_get_contents($p.'/'.basename($file));if(!is_string($body)||!hash_equals((string)($meta['hashes'][$file]??''),hash('sha256',$body)))throw new RuntimeException('Respaldo incompleto o alterado.');$out[$file]=$body;}return $out;}

function sfem_bundle():array{$lock=fopen(sfem_dir().'/apply.lock','c');if(!$lock||!flock($lock,LOCK_SH))throw new RuntimeException('No se pudo leer la versión de código.');try{$sources=sfem_sources();return ['sources'=>$sources,'hashes'=>array_map(static fn($v)=>hash('sha256',$v),$sources)];}finally{flock($lock,LOCK_UN);fclose($lock);}}

function sfem_save_settings(array $input):void{$lock=fopen(sfem_dir().'/settings.lock','c');if(!$lock||!flock($lock,LOCK_EX))throw new RuntimeException('No se pudo bloquear la configuración.');try{sfem_save_settings_unlocked($input);}finally{flock($lock,LOCK_UN);fclose($lock);}}

function sfem_interval_seconds(array $settings):int{return max(1,min(3650,(int)($settings['interval_days']??1)))*86400;}
function sfem_schedule_view(?array $settings=null,?array $state=null):array{$settings??=sfem_settings();$state??=sfem_read_json(sfem_dir().'/schedule.json');$last=(int)($state['last_attempt']??0);return array_merge($state,['enabled'=>!empty($settings['daily']),'interval_days'=>intdiv(sfem_interval_seconds($settings),86400),'next_attempt'=>$last>0?$last+sfem_interval_seconds($settings):null]);}
